const materialKey=selected.armorType||selected.questProfile?.split(':')[0];
const materialName={cloth:'Ткань',leather:'Кожа',mail:'Кольчуга',plate:'Латы'}[materialKey];
const materialLine=document.createElement('p');materialLine.className='az-item-material';materialLine.textContent=(materialName||'Материал не указан')+' · '+selected.label;detail.append(materialLine);
const required=selected.requiredLevel||0;

action.classList.add('az-equip-action');
action.style.cssText='min-height:44px;padding:10px 20px;border:2px solid #c7a66b;border-radius:6px;background:#344638;color:#fff4db;font-weight:700;opacity:1;text-shadow:none';
const equipReasons=[];
if(!on&&hLevel('me')<required)equipReasons.push('Требуется уровень '+required+'. Ваш уровень: '+hLevel('me')+'.');
if(!on&&!canEquipQuestGear(h,selected))equipReasons.push('Ваш класс не может носить этот предмет.');
if(equipReasons.length){
  action.style.background='#383633';action.style.color='#ddd3c1';action.style.borderColor='#827967';
  const reason=document.createElement('p');reason.className='az-equip-reason';reason.id='az-equip-reason';reason.style.cssText='color:#a32620;background:#fff0d5;padding:8px 10px;border-left:3px solid #a32620;text-align:left';reason.textContent=equipReasons.join(' ');detail.append(reason);
  action.setAttribute('aria-describedby',reason.id);action.title=reason.textContent;
}
detail.append(document.createElement('br'),action);
